# Runs two small hipBLASLt GEMMs under the rocjitsu race detector on a CPU
# runner: one through hipblaslt-bench and one generated by TensileLite and run
# by tensilelite-client. rocjitsu emulates the GPU, so no GPU is needed.
#
# The race detector reports reads of registers or LDS that are not ordered
# after the write they depend on by the required s_waitcnt or s_barrier,
# within one workgroup. A check fails if a workload fails, reports a race, or
# never reaches a matrix instruction (in which case the detector saw nothing
# relevant).
#
# Requires the BLAS test artifacts and the rocjitsu artifact
# (--blas --rocjitsu --tests), plus TensileLite's test requirements.

import json
import logging
import os
import platform
import shlex
import subprocess
import sys
from pathlib import Path

logging.basicConfig(level=logging.INFO)

THEROCK_BIN_DIR = os.getenv("THEROCK_BIN_DIR")
AMDGPU_FAMILIES = os.getenv("AMDGPU_FAMILIES", "")
SCRIPT_DIR = Path(__file__).resolve().parent
THEROCK_DIR = SCRIPT_DIR.parent.parent.parent
REPORT_DIR = Path(
    os.getenv("ROCJITSU_RACE_REPORT_DIR", THEROCK_DIR / "rocjitsu-race-reports")
).resolve()
HIPBLASLT_BENCH_TIMEOUT_SECONDS = 180
TENSILELITE_TIMEOUT_SECONDS = 420

# AMDGPU family prefix -> (TensileLite GPU target, rocjitsu device config).
TARGETS = {
    "gfx94": ("gfx942", "gfx942_cdna3_kmd.json"),
    "gfx950": ("gfx950", "gfx950_mi355x_kmd.json"),
}

# A single reduced TensileLite benchmark: an f32 NT GEMM using MFMA with A
# read directly to VGPRs.
TENSILELITE_CONFIG = """\
GlobalParameters:
  NumElementsToValidate: -1
  DataInitTypeBeta: 0
  DataInitTypeAlpha: 1
  Device: 0
  CpuThreads: 1
  PrintSolutionRejectionReason: True

BenchmarkProblems:
  -
    - OperationType: GEMM
      DataType: s
      TransposeA: False
      TransposeB: True
      UseBeta: True
      Batched: True
    - InitialSolutionParameters:
      BenchmarkCommonParameters:
        - KernelLanguage: ["Assembly"]
      ForkParameters:
        - MatrixInstruction:
          - [16, 16, 4, 1, 1, 2, 3, 2, 2]
        - PrefetchGlobalRead: [2]
        - PrefetchLocalRead: [1]
        - DepthU: [32]
        - VectorWidthA: [-1]
        - VectorWidthB: [-1]
        - GlobalReadVectorWidthA: [-1]
        - GlobalReadVectorWidthB: [-1]
        - LocalReadVectorWidth: [-1]
        - TransposeLDS: [-1]
        - LdsBlockSizePerPadA: [-1]
        - LdsBlockSizePerPadB: [-1]
        - LdsPadA: [-1]
        - LdsPadB: [-1]
        - StaggerU: [16]
        - StaggerUStride: [-1]
        - WorkGroupMapping: [1]
        - 1LDSBuffer: [-1]
        - WorkGroupMappingXCC: [8]
        - WorkGroupMappingXCCGroup: [-1]
        - GlobalSplitU: [1]
        - GlobalSplitUAlgorithm: ["MultipleBuffer"]
        - GlobalReadPerMfma: [1.0]
        - LocalWritePerMfma: [-1]
        - StoreRemapVectorWidth: [0]
        - StoreVectorWidth: [-1]
        - SourceSwap: [True]
        - NumElementsPerBatchStore: [16]
        - ClusterLocalRead: [1]
        - DirectToVgprA: [True]
        - DirectToVgprB: [False]
        - WorkGroup: [[32, 4, 4]]
      BenchmarkJoinParameters:
      BenchmarkFinalParameters:
        - ProblemSizes:
          - Exact: [32, 32, 1, 32]
"""


def select_target() -> tuple[str, str]:
    for prefix, target in TARGETS.items():
        if AMDGPU_FAMILIES.startswith(prefix):
            return target
    logging.error(
        f"No rocjitsu race check for AMDGPU_FAMILIES='{AMDGPU_FAMILIES}'; "
        f"supported prefixes are {sorted(TARGETS)}"
    )
    raise SystemExit(1)


def require(path: Path, description: str) -> Path:
    if not path.exists():
        logging.error(f"{description} not found: {path}")
        raise SystemExit(1)
    return path


def find_libomp_dir(rocm_path: Path) -> Path:
    # The LLVM runtime directory is flat unless TheRock enables per-target
    # runtime directories.
    llvm_lib = rocm_path / "lib" / "llvm" / "lib"
    for directory in (llvm_lib, llvm_lib / f"{platform.machine()}-unknown-linux-gnu"):
        if (directory / "libomp.so").exists():
            return directory
    logging.error(f"libomp.so not found under {llvm_lib}")
    raise SystemExit(1)


def write_rocjitsu_config(base_config: Path, output: Path, sink_dir: Path):
    config = json.loads(base_config.read_text())
    plugins = config.setdefault("plugins", {})
    plugins["race"] = {}
    plugins["logging"] = {}
    config["sinks"] = {"types": ["stderr", "file"], "dir": str(sink_dir)}
    output.write_text(json.dumps(config, indent=2) + "\n")


def run_under_rocjitsu(
    name: str,
    rocjitsu: Path,
    base_config: Path,
    workload: list[str],
    env: dict[str, str],
    timeout: int,
) -> tuple[list[str], str]:
    """Runs one workload; returns the reasons it failed, if any, and its output."""
    work_dir = REPORT_DIR / name
    sink_dir = work_dir / "sinks"
    sink_dir.mkdir(parents=True, exist_ok=True)
    run_config = work_dir / "rocjitsu.json"
    write_rocjitsu_config(base_config, run_config, sink_dir)

    cmd = [str(rocjitsu), "--config", str(run_config), "--", *workload]
    logging.info(f"++ Exec [{work_dir}]$ {shlex.join(cmd)}")
    try:
        result = subprocess.run(
            cmd,
            cwd=work_dir,
            env=env,
            stdout=subprocess.PIPE,
            stderr=subprocess.STDOUT,
            text=True,
            timeout=timeout,
        )
        output, returncode = result.stdout, result.returncode
    except subprocess.TimeoutExpired as e:
        output = e.stdout or ""
        if isinstance(output, bytes):
            output = output.decode(errors="replace")
        returncode = None
    print(output, flush=True)

    failures = []
    if returncode is None:
        failures.append(f"timed out after {timeout} seconds")
    elif returncode != 0:
        failures.append(f"exited with status {returncode}")

    race_log = sink_dir / "race.log"
    race_text = race_log.read_text(errors="replace") if race_log.exists() else ""
    if "[rocjitsu] Kernel dispatch:" not in race_text:
        failures.append(f"race detector recorded no kernel dispatch in {race_log}")
    race_lines = [line for line in race_text.splitlines() if line.startswith("RACE ")]
    if race_lines:
        failures.append(f"race detector reported {len(race_lines)} race(s)")
        print(race_text, flush=True)

    logging_log = sink_dir / "logging.log"
    logging_text = (
        logging_log.read_text(errors="replace") if logging_log.exists() else ""
    )
    if "[rocjitsu] mfma detected in dispatch " not in logging_text:
        failures.append("no MFMA dispatch reached; the race check is inconclusive")
    return failures, output


def main():
    if THEROCK_BIN_DIR is None:
        logging.error("env(THEROCK_BIN_DIR) is not set. Set it before running tests.")
        raise SystemExit(1)
    bin_dir = Path(THEROCK_BIN_DIR).resolve()
    rocm_path = bin_dir.parent
    gpu_target, config_name = select_target()

    rocjitsu = require(bin_dir / "rocjitsu", "rocjitsu launcher")
    base_config = require(
        rocm_path / "share" / "rocjitsu" / "configs" / config_name, "rocjitsu config"
    )
    bench = require(bin_dir / "hipblaslt-bench", "hipblaslt-bench")
    tensilelite_root = require(
        rocm_path / "share" / "hipblaslt" / "tensilelite", "TensileLite test tree"
    )
    tensile = require(tensilelite_root / "tensilelite" / "bin" / "Tensile", "Tensile")
    client = require(
        rocm_path / "libexec" / "hipblaslt" / "tensilelite" / "tensilelite-client",
        "tensilelite-client",
    )
    cxx = require(bin_dir / "amdclang++", "amdclang++")

    env = os.environ.copy()
    env["ROCM_PATH"] = str(rocm_path)
    env["PATH"] = os.pathsep.join(
        [str(bin_dir), str(rocm_path / "lib" / "llvm" / "bin"), env.get("PATH", "")]
    )
    env["LD_LIBRARY_PATH"] = os.pathsep.join(
        filter(
            None,
            [
                str(rocm_path / "lib"),
                str(rocm_path / "lib" / "rocm_sysdeps" / "lib"),
                str(rocm_path / "lib" / "llvm" / "lib"),
                str(find_libomp_dir(rocm_path)),
                env.get("LD_LIBRARY_PATH", ""),
            ],
        )
    )
    env["PYTHONPATH"] = os.pathsep.join(
        filter(None, [str(tensilelite_root), env.get("PYTHONPATH", "")])
    )
    env["HSA_ENABLE_SDMA"] = "1"

    REPORT_DIR.mkdir(parents=True, exist_ok=True)
    subprocess.run([str(rocjitsu), "--version"], env=env, check=True)

    results = {}
    # Run both workloads even if the first fails, so one CI attempt shows both.
    results["hipblaslt-bench"], _ = run_under_rocjitsu(
        "hipblaslt-bench",
        rocjitsu,
        base_config,
        [
            str(bench),
            "--precision",
            "f32_r",
            # Also exercises the device-side HPL initialization kernels.
            "--initialization",
            "hpl",
            "--verify",
            "-m",
            "128",
            "-n",
            "128",
            "-k",
            "128",
            "--iters",
            "1",
            "--cold_iters",
            "0",
        ],
        env,
        HIPBLASLT_BENCH_TIMEOUT_SECONDS,
    )

    tensile_dir = REPORT_DIR / "tensilelite"
    tensile_dir.mkdir(parents=True, exist_ok=True)
    tensile_config = tensile_dir / "f32_nt_32x32.yaml"
    tensile_config.write_text(TENSILELITE_CONFIG)
    failures, output = run_under_rocjitsu(
        "tensilelite",
        rocjitsu,
        base_config,
        [
            sys.executable,
            str(tensile),
            str(tensile_config),
            str(tensile_dir / "output"),
            "--prebuilt-client",
            str(client),
            "--gpu-targets",
            gpu_target,
            "--library-format",
            "msgpack",
            "--cxx-compiler",
            str(cxx),
        ],
        env,
        TENSILELITE_TIMEOUT_SECONDS,
    )
    if "PASSED" not in output:
        failures.append("TensileLite did not report a passing validation")
    results["tensilelite"] = failures

    failed = False
    for name, failures in results.items():
        for failure in failures:
            logging.error(f"{name}: {failure}")
            failed = True
    if failed:
        raise SystemExit(1)
    logging.info("rocjitsu race checks passed without race reports")


if __name__ == "__main__":
    main()
